
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_bb1k_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_bb1k", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.564143754337854e+00, -2.516336259090811e+00, -2.449379976327158e+00, -2.356698918082653e+00, -2.230555114443177e+00, -2.062969097779860e+00, -1.847879892503467e+00, -1.584980448339383e+00, -1.284648510326690e+00, -9.696738356745657e-01, -6.637324437323088e-01, -4.666394380461525e-01, -3.878364487817785e-01, -3.163503421326014e-01, -2.303579992280459e-01, -1.486202929021246e-01, -9.069701517516536e-02, -5.568959430772856e-02, -3.538888923827123e-02, -2.419768920428080e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


